// === Tab: mySketch ===
//Thanks to Aaron Reuland, a_ soluble_fish, for the basis code

let font;
let restPoints = [];
let balloons = [];
let balloonIndex = 0;
let confettis = [];
let confettiIndex = 0;
let colors = [ "#1294B5",  "#DF3C29", "#C90E56", "#781823", "#67AB86", "#feba01"];
let img;

function preload() {
	font = loadFont('https://openprocessing.org/sketch/2314842/files/Mukta-ExtraBold.ttf');
	//replace this picture with picture of person 
	img = loadImage('https://openprocessing.org/sketch/2314842/files/annelies.png');
}

function setup() {
	createCanvas(800, 600);
	textFont(font);

	//	textAlign(CENTER)
	//textSize(40)
	pointsA = font.textToPoints('Gefeliciteerd', 122, 210, 95, {
		sampleFactor: 0.2,
		simplifyThreshold: 0
	})
	pointsB = font.textToPoints('Annelies', 200, 360, 95, {
		sampleFactor: 0.2,
		simplifyThreshold: 0
	})
	pointsC = font.textToPoints('66', 240, 560, 250, {
		sampleFactor: 0.15,
		simplifyThreshold: 0
	})
	pointers = concat(pointsA, pointsB);
	restPoints = concat(pointers, pointsC);
}


function draw() {
	background("#FAC19B");
	tint(255,150);
  image (img,0,0,width,height);
	if (balloons.length < restPoints.length) {
		balloons.push(new balloon(balloonIndex))
		balloonIndex++
	}

	for (let balloon of balloons) {
		balloon.float();
		balloon.show();
	}

	if (frameCount > 950) {

		confettis.push(new confetti(random(25, 125), confettiIndex % 6));
		confettis.push(new confetti(width - random(25, 125), confettiIndex % 6));
		confettiIndex += 1;
	}

	for (let c of confettis) {
		c.fall();
		c.flutter();
	}
}

class balloon {
	constructor(index) {
		this.pos = createVector(random(width), height + 10);
		this.vel = createVector(0, 0);
		this.color = colors[index % 6];
		this.acc = createVector(0, 0);
		this.target = createVector(restPoints[index].x, restPoints[index].y)
	}

	float() {
		this.vel.limit(4);
		this.acc.limit(2);
		let force = p5.Vector.sub(this.target, this.pos);
		let r = 10;
		let d = force.mag();
		if (d < r) {
			let m = map(d, 0, r, 0, 1)
			force.setMag(m)
			if (d <= 10) {
				this.resting = true;
				this.targetrest = int(random(10, 150));
				this.seeking = false;

				this.acc.setMag(0);
				this.vel.setMag(0);
			}
		} else {
			force.setMag(1.8);
		}
		this.acc.add(force);

		//this.acc.add(gravity)
		this.vel.add(this.acc);
		this.pos.add(this.vel);
	}

	show() {
		noStroke();
		fill(this.color);
		ellipse(this.pos.x, this.pos.y, 8, 10);
		ellipse(this.pos.x, this.pos.y + 5, 4, 2);
	}
}

class confetti {
	constructor(x, index) {
		this.x = x;
		this.y = -12;
		this.r = random(TWO_PI);
		this.size = random(3, 10);
		this.rspeed = random(-2, 2);
		this.colorer = colors[index];
		this.alpha = 255;
	}

	fall() {
		this.y += 1;
		this.r += this.rspeed;

		if (this.y > 500) {
			this.alpha -= 2;
		}
		if (this.alpha < 1) {
			let index = confettis.indexOf(this);
			confettis.splice(index, 1);
		}
	}

	flutter() {
		noStroke();
		rectMode(CENTER);
		let filler = color(this.colorer);
		filler.setAlpha(this.alpha);
		fill(filler);
		push()
		translate(this.x, this.y);
		rotate(this.r);
		rect(0, 0, this.size);
		pop()
	}
}

